//! Issuing delegated credentials (RFC 9345) with keys generated by
//! `browntls-crypto`.
//!
//! [`generate`] creates a fresh credential key pair, builds the
//! [`Credential`] and has the delegation certificate's key sign it, so an
//! operator (or a test) holding that key can mint short-lived credentials
//! for the TLS endpoints. The certificate key may come from any provider:
//! only its [`SigningKey`] is used.

use alloc::vec;

use browntls_crypto::curve448::ed448;
use browntls_crypto::curve25519::ed25519;
use browntls_crypto::nist::{p256, p384, p521};
use browntls_crypto::rand::OsRng;
use browntls_pki::{
    CertificateDer, PrivateKeyDer, PrivatePkcs8KeyDer, PrivateSec1KeyDer, SubjectPublicKeyInfoDer,
};

use crate::common_state::Side;
use crate::delegated_credential::{Credential, DelegatedCredential};
use crate::enums::SignatureScheme;
use crate::error::Error;
use crate::sign::SigningKey;
use crate::sync::Arc;

/// A newly issued delegated credential and its private key.
#[derive(Debug)]
pub struct IssuedDelegatedCredential {
    /// The signed credential.
    pub credential: DelegatedCredential,
    /// The credential's private key (SEC 1 for ECDSA, PKCS #8 for EdDSA),
    /// for storage or transport to the endpoint.
    pub private_key: PrivateKeyDer<'static>,
    /// The same key, loaded by the native provider.
    pub signing_key: Arc<dyn SigningKey>,
}

/// Generates a key pair for `dc_scheme` and a delegated credential for it,
/// valid until `valid_time` seconds after `end_entity`'s `notBefore`
/// (see [`crate::delegated_credential::valid_time_until`]), signed by
/// `cert_key` (the certificate's key) with the first of `cert_schemes` it
/// supports. `side` is the side that will authenticate with it.
///
/// `dc_scheme` may be an ECDSA (P-256, P-384, P-521), Ed25519 or Ed448
/// scheme; RSA credential keys are not generated here.
pub fn generate(
    side: Side,
    end_entity: &CertificateDer<'_>,
    cert_key: &dyn SigningKey,
    cert_schemes: &[SignatureScheme],
    dc_scheme: SignatureScheme,
    valid_time: u32,
) -> Result<IssuedDelegatedCredential, Error> {
    let private_key = generate_key(dc_scheme)?;
    let signing_key = super::sign::any_supported_type(&private_key)?;
    let public_key = signing_key
        .public_key()
        .map(|spki| SubjectPublicKeyInfoDer::from(spki.as_ref().to_vec()))
        .ok_or_else(|| Error::General("generated key has no public key".into()))?;
    let credential = DelegatedCredential::issue(
        side,
        end_entity,
        cert_key,
        cert_schemes,
        Credential {
            valid_time,
            dc_cert_verify_algorithm: dc_scheme,
            public_key,
        },
    )?;
    Ok(IssuedDelegatedCredential {
        credential,
        private_key,
        signing_key,
    })
}

fn generate_key(scheme: SignatureScheme) -> Result<PrivateKeyDer<'static>, Error> {
    let failed = |_| Error::FailedToGetRandomBytes;
    macro_rules! ecdsa {
        ($curve:ident) => {{
            let key = $curve::SecretKey::generate(&OsRng).map_err(failed)?;
            let mut der = vec![0u8; $curve::SEC1_PRIVATE_MAX_LEN];
            let len = key
                .to_sec1_der(&mut der)
                .map_err(|_| Error::General("SEC 1 encoding failed".into()))?;
            der.truncate(len);
            PrivateKeyDer::Sec1(PrivateSec1KeyDer::from(der))
        }};
    }
    Ok(match scheme {
        SignatureScheme::ECDSA_NISTP256_SHA256 => ecdsa!(p256),
        SignatureScheme::ECDSA_NISTP384_SHA384 => ecdsa!(p384),
        SignatureScheme::ECDSA_NISTP521_SHA512 => ecdsa!(p521),
        SignatureScheme::ED25519 => {
            let key = ed25519::SigningKey::generate(&OsRng).map_err(failed)?;
            PrivateKeyDer::Pkcs8(PrivatePkcs8KeyDer::from(key.to_pkcs8_der().to_vec()))
        }
        SignatureScheme::ED448 => {
            let key = ed448::SigningKey::generate(&OsRng).map_err(failed)?;
            PrivateKeyDer::Pkcs8(PrivatePkcs8KeyDer::from(key.to_pkcs8_der().to_vec()))
        }
        _ => {
            return Err(Error::General(
                "unsupported delegated credential scheme for key generation".into(),
            ));
        }
    })
}
